            color: #fff;
            border-bottom: var(--border-width) solid #000;
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .brand {
            font-weight: 900;
            font-size: 1.2rem;
            letter-spacing: 1px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .brand-icon {
            width: 24px;
            height: 24px;
            border: 2px solid #fff;
            border-radius: 50%;
            position: relative;
        }
        .brand-icon::after {
            content: '';
            position: absolute;
            top: 50%; left: 50%;
            transform: translate(-50%, -50%);
            width: 8px; height: 8px;
            background: var(--accent-lime);
            border-radius: 50%;
        }

        .nav-center {
            display: flex;
            gap: 20px;
        }

        .nav-item {
            text-transform: uppercase;
            font-weight: 700;
            font-size: 0.85rem;
            cursor: pointer;
            padding: 8px 16px;
            border-radius: 20px;
            transition: all 0.2s;
        }

        .nav-item.active {
            background: var(--accent-lime);
            color: #000;
        }

        .btn-connect {
            border: 1px solid var(--accent-lime);
            color: var(--accent-lime);
            padding: 8px 24px;
            border-radius: 20px;
            font-weight: 700;
            text-transform: uppercase;
            font-size: 0.8rem;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        /* --- Main Layout --- */
        main {
            display: grid;
            grid-template-columns: 1fr 450px;
            gap: 40px;
            padding: 40px;
            max-width: 1600px;
            margin: 0 auto;
            width: 100%;
            flex: 1;
        }

        @media (max-width: 1100px) {
            main { grid-template-columns: 1fr; }
        }

        .card {
            background: transparent;
            border: var(--border-width) solid #000;
            border-radius: var(--border-radius);
            padding: 25px;
            margin-bottom: 30px;
            box-shadow: 6px 6px 0px rgba(0,0,0,1); /* Hard shadow style */
