        .hero-sub { font-size: 0.8rem; color: #555; margin-top: 5px; font-family: var(--font-mono); text-transform: uppercase; }

        /* Chronograph Dial */
        .dial-container {
            width: 140px;
            height: 140px;
            border: 4px solid #000;
            border-radius: 50%;
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
            background: #fff;
        }
        .dial-ticks {
            position: absolute;
            inset: 5px;
            border-radius: 50%;
            border: 1px dashed #ccc;
        }
        .dial-hand {
            position: absolute;
            bottom: 50%;
            left: 50%;
            width: 2px;
            height: 45px;
            background: #000;
            transform-origin: bottom center;
            transform: translateX(-50%) rotate(45deg); /* Static visual representation */
            z-index: 2;
        }
        .dial-center {
            width: 8px; height: 8px; background: #000; border-radius: 50%; z-index: 3;
