        .dial-label { font-size: 0.6rem; text-transform: uppercase; color: #888; }

        /* Stats Grid */
        .stats-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 20px;
            border-top: 1px solid #eee;
            border-bottom: 1px solid #eee;
            padding: 25px 0;
            margin-bottom: 25px;
