        .stat-item h4 { font-size: 0.7rem; color: #888; text-transform: uppercase; margin-bottom: 5px; font-weight: 600; }
        .stat-val { font-size: 1.2rem; font-weight: 800; font-family: var(--font-mono); }
        .stat-sub { font-size: 0.7rem; color: #999; margin-top: 2px; }
