        }

        .quick-selects { display: flex; gap: 8px; margin-top: 8px; }
        .qs-btn {
            border: 1px solid #ddd;
            background: #f9f9f9;
            padding: 4px 10px;
            border-radius: 12px;
            font-size: 0.7rem;
            cursor: pointer;
            font-family: var(--font-mono);
