        .qs-btn:hover { background: #eee; border-color: #bbb; }

        .helper-text { font-size: 0.65rem; color: #999; margin-top: 6px; font-family: var(--font-mono); line-height: 1.4; }

        /* Spectrum Bar */
        .spectrum-container { margin: 30px 0; }
        .spectrum-track {
            height: 8px;
            background: #eee;
            border-radius: 4px;
            position: relative;
            margin: 10px 0;
