            position: absolute;
            top: -6px;
            width: 2px;
            height: 20px;
            background: #000;
        }
        .marker-label {
            position: absolute;
            top: 18px;
            left: 50%;
            transform: translateX(-50%);
            font-size: 0.65rem;
            font-weight: 800;
            white-space: nowrap;
            background: #000;
            color: #fff;
            padding: 2px 4px;
            border-radius: 2px;
        }
        .range-labels { display: flex; justify-content: space-between; font-size: 0.65rem; color: #999; font-family: var(--font-mono); }

        /* Summary Card */
        .summary-card {
            background: #F4F1EA;
            border: 1px solid #E0DED6;
            border-radius: 8px;
            padding: 20px;
            margin-bottom: 25px;
        }
