        .rule-line { display: flex; gap: 10px; margin-bottom: 12px; font-size: 0.85rem; line-height: 1.4; }
        .dot { min-width: 8px; height: 8px; border-radius: 50%; margin-top: 5px; }
        .dot.green { background: var(--accent-lime); border: 1px solid #999; }
        .dot.yellow { background: #FFD700; border: 1px solid #999; }
        .bold { font-weight: 800; }
        .fine-print { font-size: 0.65rem; color: #999; margin-top: 15px; border-top: 1px solid #ddd; padding-top: 10px; line-height: 1.4; font-family: var(--font-mono); }

        .btn-set-order {
            width: 100%;
